using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = [];

    public CatalogService()
    {
        _departments =
        [
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, quantity, structure, space, and change." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language arts." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and human civilization." },
            new() { Id = 6, Code = "BIO", Name = "Biology", Description = "Study of living organisms and life processes." },
        ];

        _instructors =
        [
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 peer-reviewed papers and leads the university's AI research lab.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Computer Science", Bio = "Dr. Martinez focuses on distributed systems and cloud computing. He spent 10 years in industry at major tech companies before joining academia.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Dr. Sarah Thompson", Title = "Professor of Mathematics", Bio = "Dr. Thompson is a renowned researcher in abstract algebra and number theory with three published textbooks.", Email = "sthompson@university.edu" },
            new() { Id = 4, Name = "Dr. James Wilson", Title = "Associate Professor of Mathematics", Bio = "Dr. Wilson specializes in applied statistics and data analysis. He consults for several Fortune 500 companies.", Email = "jwilson@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Park", Title = "Professor of Physics", Bio = "Dr. Park is an experimental physicist studying quantum optics. She has received multiple NSF grants for her research.", Email = "epark@university.edu" },
            new() { Id = 6, Name = "Dr. Michael Brown", Title = "Professor of English", Bio = "Dr. Brown is a literary scholar specializing in 19th-century American literature and creative writing.", Email = "mbrown@university.edu" },
            new() { Id = 7, Name = "Dr. Lisa Rodriguez", Title = "Associate Professor of History", Bio = "Dr. Rodriguez studies modern European history and the history of science and technology.", Email = "lrodriguez@university.edu" },
            new() { Id = 8, Name = "Dr. David Kim", Title = "Professor of Biology", Bio = "Dr. Kim is a molecular biologist researching gene expression and cellular development.", Email = "dkim@university.edu" },
        ];

        _courses =
        [
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, data representation, and an overview of major CS subfields. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 120 },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (sorting, searching, dynamic programming). Prerequisites: CS 101.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Science Hall 305", DepartmentId = 1, InstructorId = 2, IsFeatured = true, MaxEnrollment = 60 },
            new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Principles of database design, relational models, SQL, normalization, transaction processing, and an introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Science Hall 110", DepartmentId = 1, InstructorId = 2, MaxEnrollment = 45 },
            new() { Id = 4, Code = "CS 450", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and practical applications using modern frameworks.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 40 },
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 100", DepartmentId = 2, InstructorId = 3, IsFeatured = true, MaxEnrollment = 150 },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues and eigenvectors, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Math Building 205", DepartmentId = 2, InstructorId = 3, MaxEnrollment = 60 },
            new() { Id = 7, Code = "MATH 301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, regression analysis, and Bayesian methods.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Math Building 100", DepartmentId = 2, InstructorId = 4, MaxEnrollment = 80 },
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions. Co-requisite: MATH 101.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:00 PM", Location = "Physics Building 101", DepartmentId = 3, InstructorId = 5, MaxEnrollment = 100 },
            new() { Id = 9, Code = "PHYS 301", Title = "Quantum Mechanics", Description = "Wave-particle duality, the Schrödinger equation, quantum states, operators, and measurement theory.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Physics Building 310", DepartmentId = 3, InstructorId = 5, IsFeatured = true, MaxEnrollment = 30 },
            new() { Id = 10, Code = "ENG 101", Title = "English Composition", Description = "Fundamentals of academic writing: thesis development, argumentation, research methods, and revision strategies.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Humanities Hall 102", DepartmentId = 4, InstructorId = 6, MaxEnrollment = 30 },
            new() { Id = 11, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, democracy, and culture.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Humanities Hall 205", DepartmentId = 4, InstructorId = 6, MaxEnrollment = 35 },
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory through the Renaissance, covering political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Humanities Hall 310", DepartmentId = 5, InstructorId = 7, MaxEnrollment = 80 },
            new() { Id = 13, Code = "HIST 250", Title = "History of Science and Technology", Description = "Exploration of the development of scientific thought and technological innovation from the Scientific Revolution to the digital age.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Location = "Humanities Hall 310", DepartmentId = 5, InstructorId = 7, IsFeatured = true, MaxEnrollment = 40 },
            new() { Id = 14, Code = "BIO 101", Title = "Introduction to Biology", Description = "Fundamental concepts of biology including cell structure, genetics, evolution, and ecology. Includes weekly lab.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM + Tue Lab 1:00–3:00 PM", Location = "Life Sciences 100", DepartmentId = 6, InstructorId = 8, MaxEnrollment = 120 },
            new() { Id = 15, Code = "BIO 310", Title = "Molecular Biology", Description = "DNA replication, transcription, translation, gene regulation, and modern techniques in molecular biology.", Credits = 3, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Life Sciences 220", DepartmentId = 6, InstructorId = 8, MaxEnrollment = 35 },
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.Find(d => d.Id == id);

    public List<Instructor> GetInstructors() => _instructors;

    public Instructor? GetInstructor(int id) => _instructors.Find(i => i.Id == id);

    public List<Course> GetCourses() => _courses;

    public Course? GetCourse(int id) => _courses.Find(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public List<Course> SearchCourses(string? query, int? departmentId)
    {
        var results = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            results = results.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(query))
        {
            var q = query.Trim();
            results = results.Where(c =>
                c.Title.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(q, StringComparison.OrdinalIgnoreCase));
        }

        return results.ToList();
    }

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

