@page "/courses"
@inject CatalogService Catalog

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" name="q" value="@Query" class="form-control" placeholder="Search by title, code, or keyword..." />
    </div>
    <div class="col-md-4">
        <select name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                if (dept.Id == DepartmentId)
                {
                    <option value="@dept.Id" selected>@dept.Name (@dept.Code)</option>
                }
                else
                {
                    <option value="@dept.Id">@dept.Name (@dept.Code)</option>
                }
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <p class="text-muted">Showing @courses.Count course(s)</p>
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                var dept = Catalog.GetDepartments().First(d => d.Id == course.DepartmentId);
                <tr>
                    <td><strong>@course.Code</strong></td>
                    <td>@course.Title</td>
                    <td>@dept.Name</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td><a href="courses/@course.Id" class="btn btn-outline-primary btn-sm">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery(Name = "q")]
    private string? Query { get; set; }

    [SupplyParameterFromQuery]
    private int? DepartmentId { get; set; }

    private List<Course> courses = [];

    protected override void OnInitialized()
    {
        courses = Catalog.SearchCourses(Query, DepartmentId);
    }
}

@page "/enroll"
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Complete the form below to submit an enrollment request. All fields marked with * are required.</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@selectedCourseTitle</strong> has been received. You will be notified of your enrollment status via your university email.</p>
        <hr />
        <a href="enroll" class="btn btn-outline-success">Submit Another Request</a>
        <a href="courses" class="btn btn-outline-secondary ms-2">Back to Catalog</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8">
            <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger mb-3" />

                <div class="mb-3">
                    <label for="fullName" class="form-label">Full Name *</label>
                    <InputText id="fullName" @bind-Value="Model.FullName" class="form-control" />
                    <ValidationMessage For="() => Model.FullName" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID *</label>
                    <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g. S12345" />
                    <ValidationMessage For="() => Model.StudentId" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course *</label>
                    <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                        <option value="0">-- Select a course --</option>
                        @foreach (var course in Catalog.GetCourses())
                        {
                            <option value="@course.Id">@course.Code – @course.Title (@course.Credits cr)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="comments" class="form-label">Comments (optional)</label>
                    <InputTextArea id="comments" @bind-Value="Model.Comments" class="form-control" rows="3" />
                    <ValidationMessage For="() => Model.Comments" class="text-danger" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </EditForm>
        </div>

        <div class="col-md-4">
            <div class="card bg-light">
                <div class="card-body">
                    <h5 class="card-title">Need Help?</h5>
                    <p class="card-text">Contact the Registrar's Office:</p>
                    <ul class="list-unstyled">
                        <li>📧 registrar&#64;university.edu</li>
                        <li>📞 (555) 123-4567</li>
                        <li>🏢 Admin Building, Room 102</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    private int? CourseId { get; set; }

    private bool Submitted { get; set; }
    private string selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && CourseId.Value > 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(Model.CourseId);
        selectedCourseTitle = course is not null ? $"{course.Code} – {course.Title}" : "Unknown Course";
        Catalog.SubmitEnrollment(Model);
        Submitted = true;
    }
}

